contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        c.deposit{value: depositAmount}();
        uint cBalanceBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // Since the test contract is the only depositor, its credit before withdrawAll equals depositAmount.
        // However, the test must not rely on reading c.credit because it is a private mapping.
        // The rule is: withdrawAll reverts exactly when the caller's credit (depositAmount) exceeds c's balance.
        // After deposit, cBalanceBefore is the contract's balance including the deposit.
        // The precondition for revert is depositAmount > cBalanceBefore (i.e., credit exceeds balance).
        assert(reverted == (depositAmount > cBalanceBefore));
    }

    receive() external payable {}
}
